with Src as (select * from inventory where last_restock < '2023-05-01'), summary as (select year(last_restock) as last_restock_year, product_id, count(distinct quantity) as unique_stores, count(distinct quantity) as unique_products from Src group by year(last_restock), product_id) select last_restock_year, product_id, unique_stores, unique_products from summary where unique_products > 9;
